//! The installer's nonsecret catalogue (`compositions.json`): one definition
//! and one validator for the host that writes it and the installer that reads
//! it. Field order and names are the on-disk format: the host tooling writes
//! these types with `serde_json::to_vec_pretty`, so changing either changes the
//! generated bytes.

use anyhow::{Context, Result, bail, ensure};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};

pub const REPOSITORY: &str = "ghcr.io/reidond/ilex";

/// One SMBIOS rule: either `sys_vendor` + `product_name`, or `board_vendor` +
/// `board_name`, or all four.
pub type DmiMatch = BTreeMap<String, String>;

/// The identity fields the installer compares, in the order it reads them.
pub const DMI_FIELDS: [&str; 4] = ["sys_vendor", "product_name", "board_vendor", "board_name"];

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Machine {
    pub description: String,
    #[serde(rename = "match")]
    pub matches: Vec<DmiMatch>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Shell {
    pub label: String,
    pub description: String,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Composition {
    pub tag: String,
    pub machine: String,
    pub shells: Vec<String>,
}

/// The only schema of a public profile this installer knows (`Table::validate`
/// refuses any other), and the one `setup.json` records for a chosen profile.
pub const PROFILE_SCHEMA: u32 = 1;

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Profile {
    pub schema: u32,
    #[serde(rename = "display-name")]
    pub display_name: String,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Table {
    pub schema: u32,
    pub repository: String,
    pub default: String,
    #[serde(rename = "testing-tag")]
    pub testing_tag: Option<String>,
    pub machines: BTreeMap<String, Machine>,
    pub shells: BTreeMap<String, Shell>,
    pub compositions: Vec<Composition>,
    pub profiles: BTreeMap<String, Profile>,
    #[serde(rename = "security-capabilities")]
    pub security_capabilities: BTreeMap<String, serde_json::Value>,
}

/// A registry tag: `[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}`.
pub fn validate_tag(tag: &str) -> Result<()> {
    let mut bytes = tag.bytes();
    if tag.len() > 128
        || !bytes
            .next()
            .is_some_and(|b| b.is_ascii_alphanumeric() || b == b'_')
        || !bytes.all(|b| b.is_ascii_alphanumeric() || b"_.-".contains(&b))
    {
        bail!("invalid image tag {tag:?}: expected [A-Za-z0-9_][A-Za-z0-9_.-]{{0,127}}");
    }
    Ok(())
}

/// `[a-z][a-z0-9-]*`: machine and shell names.
pub fn is_name(value: &str) -> bool {
    let mut bytes = value.bytes();
    bytes.next().is_some_and(|b| b.is_ascii_lowercase())
        && bytes.all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

/// Python's `str.strip()` also removes U+001C..U+001F, which Rust's `trim`
/// keeps; the firmware strings the installer compares were stripped with it.
pub fn py_strip(value: &str) -> &str {
    value.trim_matches(|c: char| c.is_whitespace() || ('\u{1c}'..='\u{1f}').contains(&c))
}

fn has_control(value: &str) -> bool {
    value.chars().any(char::is_control)
}

/// A human-facing string: 1 to 120 characters without control characters.
fn human(value: &str) -> bool {
    let length = value.chars().count();
    0 < length && length <= 120 && !has_control(value)
}

impl Table {
    /// Parse and validate `compositions.json`.
    pub fn parse(bytes: &[u8]) -> Result<Self> {
        let table: Self =
            serde_json::from_slice(bytes).context("reading the installer composition table")?;
        table.validate()?;
        Ok(table)
    }

    /// The checks a hand-edited or stale table must fail before anything is
    /// offered: the same rules the Anaconda chooser applies on load.
    pub fn validate(&self) -> Result<()> {
        ensure!(
            self.schema == 1 && self.repository == REPOSITORY,
            "unsupported installer table schema or repository"
        );
        let mut seen = BTreeSet::new();
        for entry in &self.compositions {
            validate_tag(&entry.tag)?;
            let shells_valid = !entry.shells.is_empty()
                && entry.shells.iter().collect::<BTreeSet<_>>().len() == entry.shells.len()
                && entry.shells.iter().all(|s| is_name(s));
            let expected = std::iter::once(entry.machine.as_str())
                .chain(entry.shells.iter().map(String::as_str))
                .collect::<Vec<_>>()
                .join(".");
            if !is_name(&entry.machine)
                || entry.machine == "vm"
                || !shells_valid
                || entry.tag != expected
                || !seen.insert(entry.tag.clone())
            {
                bail!("invalid or duplicate installer composition");
            }
            let machine = self
                .machines
                .get(&entry.machine)
                .with_context(|| format!("composition {} names an unlisted machine", entry.tag))?;
            ensure!(human(&machine.description), "invalid machine description");
            for name in &entry.shells {
                let shell = self.shells.get(name).with_context(|| {
                    format!("composition {} names an unlisted shell", entry.tag)
                })?;
                ensure!(
                    human(&shell.description) && human(&shell.label),
                    "invalid shell description"
                );
            }
        }
        ensure!(
            seen.contains(&self.default) && self.default.starts_with("generic."),
            "default must name an offered generic composition"
        );
        if let Some(tag) = &self.testing_tag {
            validate_tag(tag)?;
        }
        for (name, profile) in &self.profiles {
            let length = profile.display_name.chars().count();
            ensure!(
                name.len() <= 31
                    && is_name(name)
                    && profile.schema == PROFILE_SCHEMA
                    && 0 < length
                    && length <= 256
                    && !has_control(&profile.display_name),
                "invalid public profile catalogue"
            );
        }
        for (name, machine) in &self.machines {
            for rule in &machine.matches {
                let keys: BTreeSet<&str> = rule.keys().map(String::as_str).collect();
                let pair = |a: &str, b: &str| keys == BTreeSet::from([a, b]);
                let valid_keys = pair("sys_vendor", "product_name")
                    || pair("board_vendor", "board_name")
                    || keys == BTreeSet::from(DMI_FIELDS);
                let valid_values = rule.values().all(|v| {
                    !v.is_empty() && v.chars().count() <= 128 && py_strip(v) == v && !has_control(v)
                });
                if name == "generic" || name == "vm" || !valid_keys || !valid_values {
                    bail!("invalid DMI match table");
                }
            }
        }
        Ok(())
    }

    pub fn composition(&self, tag: &str) -> Option<&Composition> {
        self.compositions.iter().find(|c| c.tag == tag)
    }

    /// The registry reference a tag installs: the testing tag when this is a
    /// testing build, otherwise the composition's own tag.
    pub fn image_reference(&self, tag: &str) -> String {
        format!(
            "{}:{}",
            self.repository,
            self.testing_tag.as_deref().unwrap_or(tag)
        )
    }

    /// Every offered tag, in table order, for messages.
    pub fn offered(&self) -> String {
        self.compositions
            .iter()
            .map(|c| c.tag.as_str())
            .collect::<Vec<_>>()
            .join(", ")
    }
}
